// Type the result of checkSlot so that callers can trust ok.
export function checkSlot(start: number, end: number) {
  if (start % 30 !== 0 || end % 30 !== 0) return { ok: false, code: 'OFF_GRID' };
  if (end <= start) return { ok: false, code: 'END_BEFORE_START' };
  return { ok: true, minutes: end - start };
}

import { checkSlot } from '../src/slot.ts';

const slot = checkSlot(480, 600);
if (!slot.ok) throw new Error(slot.code);
const minutes: number = slot.minutes;
console.log(minutes);

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { checkSlot } from '../src/slot.ts';
test('480–600 is 120 minutes', () => assert.deepEqual(checkSlot(480, 600), { ok: true, minutes: 120 }));
test('495 is off the grid', () => assert.deepEqual(checkSlot(495, 600), { ok: false, code: 'OFF_GRID' }));

