// One declared result type: ok: true carries minutes, ok: false carries a known code.
export type SlotCode = 'OFF_GRID' | 'END_BEFORE_START';
export type SlotResult = { ok: true; minutes: number } | { ok: false; code: SlotCode };

// The return type is the contract: a typo in a code is now an error on its own line.
export function checkSlot(start: number, end: number): SlotResult {
  if (start % 30 !== 0 || end % 30 !== 0) return { ok: false, code: 'OFF_GRID' };
  if (end <= start) return { ok: false, code: 'END_BEFORE_START' };
  return { ok: true, minutes: end - start };
}

