import type { BookingInput } from '../lib/rules.ts';

export type Summary = { lab: string; seats: number; status: 'PENDING' | 'CONFIRMED' };

// Declaring the return type keeps status narrow: a misspelt or unknown status is now a compile error.
// (Appending "as const" to the returned object would also pass these checks, but leaves the contract implicit.)
export function summarize(input: BookingInput): Summary {
  const pending = input.role === 'STUDENT' && input.seats > 30;
  return { lab: input.lab, seats: input.seats, status: pending ? 'PENDING' : 'CONFIRMED' };
}

